tasks.prompt:
Add src/parseQuery.js for our tiny http framework. Export parseQuery(qs) that parses a query string into an object: leading '?' optional, keys with one value map to a string, repeated keys collect values in an array (in order), and both keys and values must be URL-decoded ('+' means space).

Examples:
- parseQuery('?a=1&b=2') === deep { a: '1', b: '2' }
- parseQuery('a=1&a=3&b=2') === deep { a: ['1', '3'], b: '2' }
- parseQuery('q=a%20b') === deep { q: 'a b' }
- parseQuery('tag=a+b') === deep { tag: 'a b' }

tasks.test:
import assert from 'node:assert/strict';
import { parseQuery } from './src/parseQuery.js';
assert.deepEqual(parseQuery('?a=1&b=2'), { a: '1', b: '2' });
assert.deepEqual(parseQuery('a=1&a=3&b=2'), { a: ['1', '3'], b: '2' });
assert.deepEqual(parseQuery('q=a%20b'), { q: 'a b' });
assert.deepEqual(parseQuery('tag=a+b'), { tag: 'a b' });
assert.deepEqual(parseQuery('empty='), { empty: '' });
console.log('PASS');

