import assert from 'node:assert/strict';
import { formatJpy } from './src/jpy.js';
const norm = s => String(s).replace(/[\s\u00A0]/g, '');
assert.equal(norm(formatJpy(123400)), '\u00A5123,400');
assert.equal(norm(formatJpy(5)), '\u00A55');
assert.equal(norm(formatJpy(123456789)), '\u00A5123,456,789');
if (/\.\d\d$/.test(norm(formatJpy(123400)))) throw new Error('yen must not show minor units');
console.log('PASS');

import assert from 'node:assert/strict';
import { retry } from './src/retry.js';
let n = 0;
assert.equal(await retry(async () => { n++; return 'ok'; }), 'ok');
assert.equal(n, 1);
let calls = 0;
const flaky = async () => { calls++; if (calls < 3) throw new Error('boom ' + calls); return 'recovered'; };
assert.equal(await retry(flaky), 'recovered');
assert.equal(calls, 3);
let always = 0;
await assert.rejects(
  () => retry(async () => { always++; throw new Error('final-' + always); }),
  /final-3/
);
assert.equal(always, 3);
